class Solution {
  private int[] bit;
  private int n;

  private void add(int i, int d) {
    for (i++; i <= n; i += i & -i) bit[i] += d;
  }

  private int prefix(int i) {
    int s = 0;
    for (i++; i > 0; i -= i & -i) s += bit[i];
    return s;
  }

  public int[] minDeletions(String s, int[][] queries) {
    n = s.length();
    bit = new int[n + 2];
    char[] c = s.toCharArray();
    for (int i = 1; i < n; i++) if (c[i] == c[i - 1]) add(i, 1);
    int cnt = 0;
    for (int[] q : queries) if (q[0] == 2) cnt++;
    int[] ans = new int[cnt];
    int idx = 0;
    for (int[] q : queries) {
      if (q[0] == 1) {
        int j = q[1];
        if (j > 0 && c[j] == c[j - 1]) add(j, -1);
        if (j + 1 < n && c[j] == c[j + 1]) add(j + 1, -1);
        c[j] = c[j] == 'A' ? 'B' : 'A';
        if (j > 0 && c[j] == c[j - 1]) add(j, 1);
        if (j + 1 < n && c[j] == c[j + 1]) add(j + 1, 1);
      } else {
        ans[idx++] = prefix(q[2]) - prefix(q[1]);
      }
    }
    return ans;
  }
}
